tool.command:

  ln -f -s ${input_model_pth_path} ${input_model_pth_path}_`echo $$`.${input_model_pth_path.ext};

  ln -f -s ${input_dataset_pt_path} ${input_dataset_pt_path}_`echo $$`.${input_dataset_pt_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

train_model

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__Trainer__dq__:${properties.Trainer},__dq__Dataset__dq__:${properties.Dataset}__cc____cc__'
  #end if

  #if str($input_model_pth_path) != 'None':
    --input_model_pth_path ${input_model_pth_path}_`echo $$`.${input_model_pth_path.ext}
  #end if

  #if str($input_dataset_pt_path) != 'None':
    --input_dataset_pt_path ${input_dataset_pt_path}_`echo $$`.${input_dataset_pt_path.ext}
  #end if


  --output_model_pth_path $outname_output_model_pth_path

  --output_metrics_npz_path $outname_output_metrics_npz_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_model_pth_path}_`echo $$`.${input_model_pth_path.ext};

  rm -f ${input_dataset_pt_path}_`echo $$`.${input_dataset_pt_path.ext};


  if test -f $outname_output_model_pth_path; then mv $outname_output_model_pth_path $output_model_pth_path; fi;

  if test -f $outname_output_metrics_npz_path; then mv $outname_output_metrics_npz_path $output_metrics_npz_path; fi;
